-- =====================================================================
-- MIGRACIÓN 008: Carga de 1 Coordinador por Colegio (dbo.Usuarios1)
-- y 1 Personero por Mesa (dbo.Usuarios) con asignación en dbo.PersoneroMesa
-- Base de Datos: conteo
-- Total Coordinadores: 123 | Total Personeros: 1650
-- =====================================================================

USE conteo;
GO

BEGIN TRANSACTION;
BEGIN TRY

    -- 1. Inserción de Coordinadores (1 por Colegio) en dbo.Usuarios1
    IF OBJECT_ID('tempdb..#CoordsAte') IS NOT NULL DROP TABLE #CoordsAte;
    CREATE TABLE #CoordsAte (
        dni VARCHAR(50),
        nombre VARCHAR(150),
        rol VARCHAR(50),
        ubicacion VARCHAR(100),
        colegio VARCHAR(200),
        mesa VARCHAR(20)
    );


    SELECT C.dni, C.nombre, C.rol, C.ubicacion, C.colegio, C.mesa
    FROM #CoordsAte C
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Usuarios1 U WHERE U.dni = C.dni OR U.colegio = C.colegio);

    -- 2. Inserción de Personeros en lotes <= 500 filas
    IF OBJECT_ID('tempdb..#PersAte') IS NOT NULL DROP TABLE #PersAte;
    CREATE TABLE #PersAte (
        dni VARCHAR(50),
        nombre VARCHAR(150),
        rol VARCHAR(50),
        ubicacion VARCHAR(100),
        colegio VARCHAR(200),
        mesa VARCHAR(20)
    );





    SELECT P.dni, P.nombre, P.rol, P.ubicacion, P.colegio, P.mesa
    FROM #PersAte P
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Usuarios U WHERE U.dni = P.dni OR U.mesa = P.mesa);

    -- 3. Inserción en dbo.PersoneroMesa (Relación estricta 1:1)
    SELECT P.dni, P.mesa, 'ASIGNADO'
    FROM #PersAte P
    WHERE NOT EXISTS (
        SELECT 1 FROM dbo.PersoneroMesa PM 
        WHERE PM.personero_dni = P.dni OR PM.numero_mesa = P.mesa
    );

    COMMIT TRANSACTION;
    PRINT '✅ Migración 008 ejecutada con éxito. Coordinadores y Personeros cargados.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@ErrMsg, 16, 1);
END CATCH;
GO
